const b64uToBuffer=(value)=>{const s=String(value||'').replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(String(value||'').length/4)*4,'=');const raw=atob(s);const out=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)out[i]=raw.charCodeAt(i);return out.buffer};
const bufferToB64u=(value)=>{const bytes=new Uint8Array(value||new ArrayBuffer(0));let s='';for(const b of bytes)s+=String.fromCharCode(b);return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');};
const parseRequestOptions=(options)=>{
  if(globalThis.PublicKeyCredential?.parseRequestOptionsFromJSON){return PublicKeyCredential.parseRequestOptionsFromJSON(options)}
  return {...options,challenge:b64uToBuffer(options.challenge),allowCredentials:(options.allowCredentials||[]).map(c=>({...c,id:b64uToBuffer(c.id)})),extensions:options.extensions?options.extensions:{}};
};
const toJSON=(credential)=>{
  if(typeof credential?.toJSON==='function')return credential.toJSON();
  const r=credential.response;
  return {id:credential.id,rawId:bufferToB64u(credential.rawId),type:credential.type,response:{clientDataJSON:bufferToB64u(r.clientDataJSON),authenticatorData:bufferToB64u(r.authenticatorData),signature:bufferToB64u(r.signature),userHandle:r.userHandle?bufferToB64u(r.userHandle):null},clientExtensionResults:credential.getClientExtensionResults?.()||{}};
};
export async function startAuthentication({optionsJSON}){
  if(!globalThis.PublicKeyCredential||!navigator.credentials?.get)throw new Error('Passkeys are not supported by this browser.');
  const credential=await navigator.credentials.get({publicKey:parseRequestOptions(optionsJSON)});
  if(!credential)throw new Error('Passkey authentication was cancelled.');
  return toJSON(credential);
}
export function browserSupportsWebAuthn(){return !!(globalThis.PublicKeyCredential&&navigator.credentials?.get)}
export function browserSupportsPasskeys(){return Promise.resolve(browserSupportsWebAuthn())}
